def label_shape(content, target_width, center_y):
    sketch = Compound(children=import_svg(StringIO(name_svg)))
    sketch = scale(sketch, by=target_width / sketch.bounding_box().size.X)
    bb = sketch.bounding_box()
    sketch = Pos(-(bb.min.X+bb.max.X)/2, center_y-(bb.min.Y+bb.max.Y)/2) * sketch
    return Pos(0, 0, plate_thickness) * extrude(sketch, amount=relief_height)
# uploaded_logo: source traced from the supplied image, including the white letter counters.
logo_shapes = import_svg(StringIO(logo_svg), align=None)
red_sketch = Compound(children=[s for s in logo_shapes if s.label == "logo_red"])
white_sketch = Compound(children=[s for s in logo_shapes if s.label.startswith("logo_white_")])
assert len(red_sketch.faces()) == 1
assert len(white_sketch.faces()) == 8
logo_scale = title_width / red_sketch.bounding_box().size.X
red_sketch = scale(red_sketch, by=logo_scale)
white_sketch = scale(white_sketch, by=logo_scale)
logo_bb = red_sketch.bounding_box()
# Profiles share a local frame centred on the logo for both mating pieces.
logo_origin_shift = Pos(-(logo_bb.min.X+logo_bb.max.X)/2, -(logo_bb.min.Y+logo_bb.max.Y)/2)
red_profile = logo_origin_shift * red_sketch
white_profile = logo_origin_shift * white_sketch
# logo_recess: free implementation, 0.2 mm radial clearance and 0.6 mm insertion depth.
recess_profile = offset(red_profile, amount=logo_recess_clearance, kind=Kind.ARC)
pocket = Pos(0,title_y,recess_floor_z) * extrude(recess_profile, amount=logo_recess_depth)
base = base - pocket
assert abs(pocket.bounding_box().size.Z-logo_recess_depth) < 0.00001
assert abs(pocket.bounding_box().min.Z-recess_floor_z) < 0.00001
name = label_shape("李山迎 Joshua", name_width, name_y)
name_bb = name.bounding_box()
assert abs(name_bb.size.X - name_width) < 0.00001
assert abs((name_bb.min.X + name_bb.max.X)/2) < 0.00001
print("Source Han Sans CN Bold name width, height, relief:", name_bb.size.X, name_bb.size.Y, name_bb.size.Z)
assert name.bounding_box().min.Y > qr_y + qr_width/2 + quiet_zone
assert pocket.bounding_box().max.Y < plate_height/2
assert pocket.bounding_box().min.Y > name.bounding_box().max.Y
features = [name]
# Exact contiguous square modules grouped into horizontal runs, with no rounding or inset.
for row_index, row in enumerate(qr_rows):
    c = 0
    while c < module_count:
        if row[c] == "0":
            c += 1
            continue
        end = c + 1
        while end < module_count and row[end] == "1":
            end += 1
        x = -qr_width/2 + (c+end)*module_pitch/2
        y = qr_y + qr_width/2 - (row_index+0.5)*module_pitch
        features.append(Pos(x,y,plate_thickness) * Box((end-c)*module_pitch,module_pitch,relief_height,align=(Align.CENTER,Align.CENTER,Align.MIN)))
        c = end
# Black name and QR fuse to the continuous white backing.
# The independent logo insert is built by part logo_insert.
plaque_body = base.fuse(*features)
assert len(plaque_body.solids()) == 1, "Every raised region must connect to the backing"
assert abs(plaque_body.bounding_box().size.Y-plate_height) < 0.00001
assert abs(plaque_body.bounding_box().size.X-plate_width) < 0.00001
assert abs(plaque_body.bounding_box().size.Z-(plate_thickness+relief_height)) < 0.00001
plaque_body.color = srgb("#faf8f3")
for face in plaque_body.faces():
    if face.bounding_box().min.Z >= plate_thickness - 0.00001:
        face.color = srgb("#161616")
print("Plate:", plate_width, plate_height, plate_thickness, "relief:", relief_height)
print("QR modules:",module_count,"pitch:",module_pitch,"quiet zone:",quiet_zone)
print("Backing/name/QR connected solids:",len(plaque_body.solids()))
print("Logo recess depth, floor, per-side clearance:",logo_recess_depth,recess_floor_z,logo_recess_clearance)
publish("plaque_body",plaque_body,"二维码牌底板",material="pla")
